import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.G0y0PQA7.js";const s="/relio/shots/en/cat-tabs.png",r="/relio/shots/en/cat-multi-select.png",m=JSON.parse('{"title":"Split the model into categories","description":"","frontmatter":{},"headers":[],"relativePath":"en/quick/categories.md","filePath":"en/quick/categories.md"}'),n={name:"en/quick/categories.md"};function l(c,e,g,h,d,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="split-the-model-into-categories" tabindex="-1">Split the model into categories <a class="header-anchor" href="#split-the-model-into-categories" aria-label="Permalink to &quot;Split the model into categories&quot;">​</a></h1><p>When a model has many tables, split it into categories by business area and look only at the part you need.</p><ol><li><p><strong>Create a category</strong> — Pick Category (<kbd>C</kbd>) in the palette and drag on the canvas to make an area. Tables placed inside the area belong to that category. Edit names and the list in Model › Category › Manage categories….</p></li><li><p><strong>View a category tab</strong> — In the category tabs below the canvas, click &quot;All&quot; or a category. A category tab shows only what belongs to that category, and each tab remembers where you were looking.</p><figure class="shot" data-scene="cat-tabs"><img src="'+s+'" alt="Category tabs below the canvas — All and one tab per category" loading="lazy"><figcaption>Category tabs below the canvas — All and one tab per category</figcaption></figure></li><li><p><strong>View several categories together</strong> — <kbd>Ctrl</kbd>+click (<kbd>⌘</kbd>+click on macOS) another tab to add or remove that category. A plain click shows that tab alone.</p><figure class="shot" data-scene="cat-multi-select"><img src="'+r+'" alt="Two category tabs selected together — the tab with the bold underline is the main category" loading="lazy"><figcaption>Two category tabs selected together — the tab with the bold underline is the main category</figcaption></figure></li></ol><p>When you view several together, the tab with the bold underline (the category you chose last) is the main category. Tables you create or paste in this view go into the main category.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>The multi-selection is not saved in the file. Only the main category is kept, so the file stays the same even if you also use ERMaster.</p></div><p><strong>More</strong> → <a href="/relio/en/features/categories">Categories</a></p>',6)])])}const y=t(n,[["render",l]]);export{m as __pageData,y as default};
